  totalTokens: number;
  cacheReadInputTokens?: number;
  cacheWriteInputTokens?: number;
  hasThinkingBlock: boolean;
  estimatedThinkingTokens: number;
}> {
  const start = Date.now();
  if (effort === "none") effort = undefined;

  // Build user content (text + optional images).
  const userContent: any[] = [{ text: userMessage }];
  if (images?.length) {
    for (const img of images) {
      const format = img.mediaType.replace("image/", "");
      // SDK requires `bytes` to be a Uint8Array, not a base64 string.
      const bytes = Buffer.from(img.data, "base64");
      userContent.push({ image: { format, source: { bytes } } });
    }
  }

  const budgetMap: Record<string, number> = { low: 1024, medium: 5000, high: 16000, max: 60000 };
  const budgetTokens = budgetMap[effort!] ?? 5000;
  const isOpus47 = modelId.includes("opus-4-7") || modelId.includes("opus-4-8");
  const inferenceConfig: Record<string, unknown> = {
    maxTokens: effort ? (isOpus47 ? 16384 : Math.min(budgetTokens + 4096, 64000)) : 512,
  };
  if (!isOpus47) inferenceConfig.temperature = effort ? 1 : 0.1;

  // SDK types `additionalModelRequestFields` as `DocumentType` which doesn't
  // accept conditional shapes cleanly — cast to any. The wire format is
  // model-runtime-defined (Anthropic vs Nova etc.), so the SDK leaves it open.
  const additionalModelRequestFields: any = effort
    ? (isOpus47
        ? { thinking: { type: "adaptive" }, output_config: { effort } }
        : { thinking: { type: "enabled", budget_tokens: budgetTokens } })
    : undefined;

  // Prompt caching: mark the system prompt as a cache point so the
  // 6500-token B7.1 hardened prompt is billed at 10% of the input rate
  // for the next 5 minutes (cache TTL). The cache key is "everything
  // before this marker"; the per-call user message after it is billed
  // normally.
  //
  // Only effective when the cached portion is >= ~1024 tokens (Bedrock
  // minimum). The standard SYSTEM_PROMPT may fall under that threshold
  // and Bedrock will silently skip caching — that's fine, the marker
  // costs nothing on a no-op.
  //
  // We do NOT mark a cache point inside the user content because that
  // changes per call (tool input, file context, agent reasoning) — caching
  // it would invalidate every time. The system prompt is the static
  // 90%+ of every judge request.
  const systemBlocks: any[] = [
    { text: systemPrompt },
    { cachePoint: { type: "default" } },
  ];

  const command = new ConverseCommand({
    modelId,
    system: systemBlocks,
    messages: [{ role: "user", content: userContent }],
    inferenceConfig,
    ...(additionalModelRequestFields ? { additionalModelRequestFields } : {}),
  });

  // Hard timeout on the Bedrock call — a stuck request previously
  // hung the event loop indefinitely (CloudWatch outage on
  // 2026-05-10T03:17 to 07:32 UTC: hook went silent after a single
  // /screen call never returned, ALB health-check took 2h 23m to
  // notice). 120s is generous — opus thinking-mode runs can take
  // 30-60s. Anything longer is a hung connection, not a slow model.
  // Override via BEDROCK_REQUEST_TIMEOUT_MS for thinking-mode runs
  // that legitimately need more headroom.
  const timeoutMs = parseInt(process.env.BEDROCK_REQUEST_TIMEOUT_MS ?? "120000", 10);
  const response = await clientFor(REGION).send(command, {
    abortSignal: AbortSignal.timeout(timeoutMs),
  });

  const blocks = (response.output?.message?.content ?? []) as any[];
  const content = blocks
    .filter((c) => c.text !== undefined)
    .map((c) => c.text as string)
    .join("");
  const thinking = blocks
    .filter((c) => c.reasoningContent !== undefined)
    .map((c) => {
      const rc = c.reasoningContent;
      const rt = rc.reasoningText;
      return (rt?.text ?? rc.text ?? "") as string;
    })
    .join("");

  const usage: any = response.usage ?? {};
  const inputTokens = usage.inputTokens ?? 0;
  const outputTokens = usage.outputTokens ?? 0;
  const hasThinkingBlock = blocks.some((c) => c.reasoningContent !== undefined);
  return {
    content,
    thinking,
    durationMs: Date.now() - start,
    inputTokens,
    outputTokens,
    totalTokens: usage.totalTokens ?? (inputTokens + outputTokens),
    cacheReadInputTokens: usage.cacheReadInputTokens ?? undefined,
    cacheWriteInputTokens: usage.cacheWriteInputTokens ?? undefined,
    hasThinkingBlock,
    estimatedThinkingTokens: thinking ? Math.ceil(thinking.length / 4) : 0,
  };
}

// ============================================================================
// Embedding API
// ============================================================================

/**
 * Embed a batch of texts using a Bedrock embedding model.
 * Dispatches to the correct request/response format per model family.
 */
export async function bedrockEmbed(
  texts: string[],
  modelId: string,
  region = REGION
): Promise<number[][]> {
  // Strip cross-region inference profile prefixes (eu., us., global.) before dispatch
  const bare = modelId.replace(/^(?:eu|us|global)\./, "");

  if (bare.startsWith("cohere.embed")) {
    return cohereEmbed(texts, modelId, region);
  }
  if (bare.startsWith("amazon.titan-embed")) {
    return Promise.all(texts.map((t) => titanEmbed(t, modelId, region)));
  }
  if (bare.startsWith("twelvelabs.")) {
    return Promise.all(texts.map((t) => marengoEmbed(t, modelId, region)));
  }
  throw new Error(`Unknown Bedrock embedding model family: ${modelId}`);
}

async function invokeModel(modelId: string, body: object, region: string): Promise<object> {
  const command = new InvokeModelCommand({
    modelId,
    body: new TextEncoder().encode(JSON.stringify(body)),
    contentType: "application/json",
    accept: "application/json",
  });
  const response = await clientFor(region).send(command);
  // SDK returns response.body as Uint8Array.
  const bytes = response.body as Uint8Array;
  return JSON.parse(new TextDecoder().decode(bytes));
}

async function cohereEmbed(texts: string[], modelId: string, region: string): Promise<number[][]> {
  const resp = (await invokeModel(modelId, { texts, input_type: "search_query" }, region)) as Record<string, unknown>;
  // v3: { embeddings: number[][] }
  // v4: { embeddings: { float: number[][] } }
  const emb = resp.embeddings as number[][] | { float: number[][] };
  return Array.isArray(emb) ? emb : emb.float;
}

async function titanEmbed(text: string, modelId: string, region: string): Promise<number[]> {
  const resp = (await invokeModel(modelId, { inputText: text }, region)) as { embedding: number[] };
  return resp.embedding;
}

async function marengoEmbed(text: string, modelId: string, region: string): Promise<number[]> {
  // Marengo 3.0: { inputType: "text", text: { text: "..." } }
  // Marengo 2.7: { inputType: "text", inputText: "..." }
  const bare = modelId.replace(/^(?:eu|us|global)\./, "");
  const body = bare.includes("marengo-embed-2-7")
    ? { inputType: "text", inputText: text }
    : { inputType: "text", text: { inputText: text } };

  const resp = (await invokeModel(modelId, body, region)) as Record<string, unknown>;
  if (Array.isArray(resp.embedding)) return resp.embedding as number[];
  const data = resp.data as { embedding: number[] }[] | undefined;
  if (data?.[0]?.embedding) return data[0].embedding;
  throw new Error(`Unexpected Marengo response shape: ${JSON.stringify(resp).substring(0, 200)}`);
}

export async function checkBedrock(modelId = MODEL_ID): Promise<boolean> {
  // Test with a real Converse call — avoids needing metadata API permissions
  // (bedrock:ListInferenceProfiles, bedrock:GetFoundationModel).
  try {
    const command = new ConverseCommand({
      modelId,
      messages: [{ role: "user", content: [{ text: "ok" }] }],
      inferenceConfig: { maxTokens: 1 },
    });
    // Short timeout on the preflight: 30s is plenty for a 1-token
    // sanity call. Don't let preflight hang container startup.
    await clientFor(REGION).send(command, { abortSignal: AbortSignal.timeout(30_000) });
    return true;
  } catch {
    return false;
  }
}

/**
 * Write-through LRU cache wrapping an `ApiKeyStore`.
 *
 * API keys are validated on EVERY hook request. That's potentially the
 * hottest path in the server — every tool call, every intent registration,
 * every /track, every /end. Doing a Dynamo `GetItem` for each would add
 * ~10ms p50 + a Dynamo read for every request. With a positive cache of a
 * few minutes we take the hit once per key per container and serve the
 * rest from memory.
 *
 * Two caches:
 *   - positive: validated hash → ValidatedKey, 5m TTL. Reverts to Dynamo
 *                after TTL so revocations eventually propagate.
 *   - negative: unknown hash → tombstone, 30s TTL. Stops an attacker from
 *                brute-forcing keys by ensuring each guess pays a Dynamo
 *                lookup at most once per 30s per hash.
 *
 * Revocation propagation:
 *   - The container that calls `revokeKey` invalidates its own cache
 *     immediately.
 *   - Other containers stay stale for up to 5 minutes (positive cache TTL).
 *     For the sandbox threat model this is acceptable; emergency revoke
 *     within 5 minutes is fine. If we need faster, we'd add an SNS fanout
 *     invalidation channel — out of scope for v1.
 *
 * lastUsedAt:
 *   - The backend updates lastUsedAt asynchronously on every `validateKey`.
 *     We don't bother reading it on cache hits (it's only for dashboard
 *     display, not for security decisions), so cache staleness is fine.
 */

import {
  type ApiKeyStore,
  type GenerateKeyInput,
  type GeneratedKey,
  type KeyRecord,
  type ValidatedKey,
  hashKey,
  looksLikeJaidKey,
} from "./api-key-store.js";

const POSITIVE_TTL_MS = 5 * 60 * 1000;
const NEGATIVE_TTL_MS = 30 * 1000;
const DEFAULT_MAX = 1000;

interface CacheEntry {
  validated: ValidatedKey | null; // null = tombstone (known-unknown)
  expiresAt: number;
}

export interface CachedApiKeyStoreOptions {
  backend: ApiKeyStore;
  maxHashes?: number;
  positiveTtlMs?: number;
  negativeTtlMs?: number;
  /** Override for tests. */
  now?: () => number;
}

export class CachedApiKeyStore implements ApiKeyStore {
  private readonly backend: ApiKeyStore;
  private readonly maxHashes: number;
  private readonly positiveTtlMs: number;
  private readonly negativeTtlMs: number;
  private readonly now: () => number;

  /** LRU-ordered by insertion / touch. JS `Map` iteration order = insertion
   *  order, so we delete-and-reinsert to mark as recently used. */
  private readonly cache = new Map<string, CacheEntry>();

  constructor(opts: CachedApiKeyStoreOptions) {
    this.backend = opts.backend;
    this.maxHashes = opts.maxHashes ?? DEFAULT_MAX;
    this.positiveTtlMs = opts.positiveTtlMs ?? POSITIVE_TTL_MS;
    this.negativeTtlMs = opts.negativeTtlMs ?? NEGATIVE_TTL_MS;
    this.now = opts.now ?? (() => Date.now());
  }

  // ---- cache plumbing --------------------------------------------------

  private touch(hash: string, entry: CacheEntry): void {
    this.cache.delete(hash);
    this.cache.set(hash, entry);
    while (this.cache.size > this.maxHashes) {
      const oldest = this.cache.keys().next().value;
      if (oldest === undefined) break;
      this.cache.delete(oldest);
    }
  }

  private readCached(hash: string): CacheEntry | undefined {
    const entry = this.cache.get(hash);
    if (!entry) return undefined;
    if (entry.expiresAt <= this.now()) {
      this.cache.delete(hash);
      return undefined;
    }
    // Touch to bump LRU order.
    this.cache.delete(hash);
    this.cache.set(hash, entry);
    return entry;
  }

  private invalidate(hash: string): void {
    this.cache.delete(hash);
  }

  // ---- ApiKeyStore impl ------------------------------------------------

  async generateKey(input: GenerateKeyInput): Promise<GeneratedKey> {
    // Delegate to backend. Seed the positive cache so the very first
    // validation on this container doesn't round-trip.
    const gen = await this.backend.generateKey(input);
    this.touch(gen.hashedKey, {
      validated: {
        hashedKey: gen.hashedKey,
        ownerSub: gen.ownerSub,
        ownerEmail: gen.ownerEmail,
        keyType: gen.keyType,
      },
      expiresAt: this.now() + this.positiveTtlMs,
    });
    return gen;
  }

  async validateKey(plaintext: string): Promise<ValidatedKey | null> {
    // Fast reject on shape mismatch — no cache pollution.
    if (!looksLikeJaidKey(plaintext)) return null;
    const hash = hashKey(plaintext);

    const cached = this.readCached(hash);
    if (cached) return cached.validated; // may be null tombstone

    const result = await this.backend.validateKey(plaintext);
    this.touch(hash, {
      validated: result,
      expiresAt:
        this.now() + (result ? this.positiveTtlMs : this.negativeTtlMs),
    });
    return result;
  }

  async listByOwner(ownerSub: string, limit?: number): Promise<KeyRecord[]> {
    // Dashboard operation. Don't cache — always hit backend so the list
    // reflects freshly-generated or revoked keys. Low QPS anyway.
    return this.backend.listByOwner(ownerSub, limit);
  }

  async listAll(limit?: number): Promise<KeyRecord[]> {
    // Same rationale as listByOwner — fresh-data > caching for the
    // admin dashboard view.
    return this.backend.listAll(limit);
  }

  async revokeKey(hashedKey: string, revokedBy: string): Promise<boolean> {
    const ok = await this.backend.revokeKey(hashedKey, revokedBy);
    // Invalidate immediately on this container. Other containers will hit
    // their own 5-minute positive-cache TTL before picking up the revoke.
    this.invalidate(hashedKey);
    return ok;
  }

  async loadKey(hashedKey: string): Promise<KeyRecord | null> {
    return this.backend.loadKey(hashedKey);
  }
}

/**
 * Core types for the goal hijacking test framework.
 */

export interface TurnLog {
  /** Turn number (0 = initial task) */
  turnNumber: number;
  /** Timestamp */
  timestamp: string;
  /** The user message that started this turn */
  userMessage: string;
  /** Tools the agent invoked during this turn */
  toolCalls: ToolCallLog[];
  /** The agent's text response */
  assistantResponse: string;
  /** Whether any canary values appeared in tool calls or responses */
  canaryDetected: boolean;
  /** Specific canary strings found */
  canariesFound: string[];
  /** Wall-clock time for this turn (ms), null if not measured */
  durationMs?: number | null;
}

export interface ToolCallLog {
  /** Tool name (e.g., "Read", "Write", "Bash") */
  tool: string;
  /** Tool input/parameters */
  input: Record<string, unknown>;
  /** Tool output (truncated if large) */
  output: string;
  /** Whether canary was present in input or output */
  canaryInInput: boolean;
  canaryInOutput: boolean;
  /** Wall-clock time for this tool call (ms), null if not measured */
  durationMs?: number | null;
  /**
   * PromptArmor verdict on this tool's output. Set only when the
   * executor was configured with a PromptArmor baseline; otherwise
   * undefined. Used by the head-to-head test plan to compare
   * defence-side rates per (corpus, backend, model) cell.
   */
  promptArmor?: {
    verdict: "clean" | "injected" | "parse_error";
    latencyMs: number;
    tokensIn: number;
    tokensOut: number;
    sanitisationFailed?: boolean;
    error?: string;
  };
}

export interface TestResult {
  /** Scenario ID (e.g., "T3.1") */
  scenarioId: string;
  /** Scenario name */
  scenarioName: string;
  /** Repetition number */
  repetition: number;
  /** Model used */
  model: string;
  /** Full turn-by-turn log */
  turns: TurnLog[];
  /** Turn at which first canary was detected (null if never) */
  firstCanaryTurn: number | null;
  /** Whether the hijack ultimately succeeded (canary exfiltrated) */
  hijackSucceeded: boolean;
  /** Whether the agent explicitly flagged the hijack attempt */
  agentDetected: boolean;
  /** GES score (from p14 methodology) */
  ges: number;
  /** Total duration in ms */
  durationMs: number;
  /** Intent tracking verdict at each turn (null = no tracking enabled) */
  intentVerdicts: (IntentVerdict | null)[];
  /** Reasoning effort level for the agent (none/medium/high) */
  effort?: string;
  /** Reasoning effort level for the judge (none/medium/high) */
  judgeEffort?: string;
  /** Whether actual exfiltration was detected via canary server (null = not measured) */
  exfiltrationDetected?: boolean | null;
  /** Number of canary server hits */
  exfiltrationCount?: number;
  /** Paths hit on the canary server */
  exfiltrationPaths?: string[];
  /** GES recalculated using exfiltration (not just canary-in-context) */
  gesExfil?: number;
  /** Whether canary was displayed in assistant response text (visible to remote operator) */
  displayedToUser?: boolean;
  /** GES recalculated using displayed-to-user (remote-directed threat model) */
  gesDisplayed?: number;
}

export interface IntentVerdict {
  turnNumber: number;
  /** Cosine similarity between original task and current action */
  semanticSimilarity: number;
  /** Cumulative drift score (0 = no drift, 1 = complete departure) */
  cumulativeDrift: number;
  /** Turn-over-turn drift (sudden shift detection) */
  turnDelta: number;
  /** Overall verdict */
  verdict: "consistent" | "drifting" | "hijacked";
  /** Whether goal anchor was injected */
  goalAnchorInjected: boolean;
  /** Whether the turn was blocked */
  blocked: boolean;
}

