          logger.getScreens();
        (result as TestResult & { promptarmorStats?: unknown }).promptarmorStats =
          logger.stats;
      }

      allResults.push(result);
    } catch (err) {
      console.error(
        `ERROR in ${t.scenario.id} rep ${t.rep + 1}: ${err instanceof Error ? err.message : String(err)}`,
      );
    }
