/**
 * SDK Hook Integration
 *
 * Wires the SessionTracker and PreToolInterceptor into the Claude
 * Agent SDK's hook system. Produces the hooks configuration object
 * that you pass to query() options.
 *
 * Hook chain:
 *   1. UserPromptSubmit → SessionTracker.registerIntent()
 *      - First call: stores original task + embedding
 *      - Subsequent: stores turn intent, measures drift from original
 *
 *   2. PreToolUse → PreToolInterceptor.evaluate()
 *      - Stage 1: Policy engine (instant allow/deny/review)
 *      - Stage 2: Embedding drift check (~50ms)
 *      - Stage 3: LLM judge (~10-15s, only for ambiguous cases)
 *      - Returns permissionDecision: allow/deny
 *      - On deny: injects systemMessage explaining why
 *
 *   3. PostToolUse → SessionTracker.recordToolCall()
 *      - Logs the completed tool call for trajectory analysis
 *
 * Available data per hook:
 *   - session_id:    identifies the session (persistent across turns)
 *   - tool_use_id:   identifies specific tool call (correlates Pre/Post)
 *   - tool_name:     the tool being called
 *   - tool_input:    parameters (file_path, command, etc.)
 *   - cwd:           working directory
 *   - agent_id:      if inside a subagent
 *
 * NOT available:
 *   - Conversation history
 *   - Previous tool outputs
 *   - The original prompt (must be captured via UserPromptSubmit)
 */

import type { HookCallback } from "@anthropic-ai/claude-agent-sdk";
import { writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { SessionTracker } from "./session-tracker.js";
import { PreToolInterceptor, type InterceptorConfig } from "./pretool-interceptor.js";

export interface DefenceHooksConfig extends InterceptorConfig {
  /** Drift threshold from original task to inject systemMessage warning (default: 0.3) */
  intentDriftWarn?: number;
  /** Drift threshold from original task to block the prompt entirely (default: 0.6) */
  intentDriftBlock?: number;
  /** Directory to write session logs (default: ./results) */
  logDir?: string;
}

const DEFAULTS = {
  intentDriftWarn: 0.3,
  intentDriftBlock: 0.6,
  logDir: "./results",
};

/**
 * Create the hooks configuration object for the SDK.
 *
 * Usage:
 *   const { hooks, tracker, interceptor } = await createDefenceHooks(config);
 *   for await (const msg of query({ prompt, options: { hooks } })) { ... }
 */
export async function createDefenceHooks(config?: DefenceHooksConfig) {
  const cfg = { ...DEFAULTS, ...config };

  const tracker = new SessionTracker(config?.embeddingModel);
  const interceptor = new PreToolInterceptor(config);
  await interceptor.preflight();

  // --- UserPromptSubmit hook ---
  // Captures original intent on first call, tracks turn intents thereafter
  const onUserPromptSubmit: HookCallback = async (input, toolUseId, ctx) => {
    const sessionId = (input as any).session_id as string;
    const prompt = (input as any).prompt as string ?? (input as any).message as string ?? "";

    const result = await tracker.registerIntent(sessionId, prompt);

    // On first call, also register with the interceptor
    if (result.isOriginal) {
      await interceptor.registerGoal(prompt);
    }

    // Check intent drift from original task
    if (result.driftFromOriginal !== null) {
      if (result.driftFromOriginal >= cfg.intentDriftBlock) {
        // Severe drift — inject warning and signal that this prompt is suspicious
        return {
          systemMessage:
            `[SECURITY] This prompt has drifted significantly from the original task ` +
            `(drift: ${result.driftFromOriginal.toFixed(3)}). The original task was: ` +
            `"${tracker.getSessionContext(sessionId).originalTask}". ` +
            `Evaluate whether continuing serves the original objective.`,
        };
      }

      if (result.driftFromOriginal >= cfg.intentDriftWarn) {
        return {
          systemMessage:
            `[REMINDER] Your original task is: "${tracker.getSessionContext(sessionId).originalTask}". ` +
            `Ensure your actions remain focused on this objective.`,
        };
      }
    }

    return {};
  };

  // --- PreToolUse hook ---
  // Evaluates every tool call through the three-stage pipeline
  const onPreToolUse: HookCallback = async (input, toolUseId, ctx) => {
    const sessionId = (input as any).session_id as string;
    const toolName = (input as any).tool_name as string;
    const toolInput = (input as any).tool_input as Record<string, unknown>;

    // Get session context for the interceptor
    const sessionCtx = tracker.getSessionContext(sessionId);

    // If we don't have an original task yet (shouldn't happen, but defensive)
    if (!sessionCtx.originalTask) {
      console.log(`  [HOOK] No original task registered for session ${sessionId.substring(0, 8)}`);
      return {};
    }

    // Evaluate through the three-stage pipeline
    const result = await interceptor.evaluate(toolName, toolInput);

    // Record the decision
    tracker.recordToolCall(
      sessionId,
      toolName,
      toolInput,
      result.allowed ? "allow" : "deny",
      result.similarity
    );

    if (!result.allowed) {
      return {
        systemMessage:
          `[SECURITY] Tool call ${toolName} was blocked. Reason: ${result.reason}. ` +
          `Stay focused on the original task: "${sessionCtx.originalTask}".`,
        hookSpecificOutput: {
          hookEventName: "PreToolUse",
          permissionDecision: "deny",
          permissionDecisionReason: `Intent tracker: ${result.reason}`,
        },
      };
    }

    return {};
  };

  // --- PostToolUse hook ---
  // Logs completed tool calls (for trajectory analysis, no blocking)
  const onPostToolUse: HookCallback = async (input, toolUseId, ctx) => {
    // Async logging — don't block the agent
    return { async: true };
  };

  // --- Stop hook ---
  // Fires when the agent finishes responding. Writes the full session log.
  const onStop: HookCallback = async (input, toolUseId, ctx) => {
    const sessionId = (input as any).session_id as string;
    if (!sessionId) return {};

    const sessionCtx = tracker.getSessionContext(sessionId);
    const summary = tracker.getSessionSummary(sessionId);
    const driftHistory = tracker.getDriftDetector(sessionId).getHistory();
    const interceptorLog = interceptor.getLog();

    const sessionLog = {
      sessionId,
      timestamp: new Date().toISOString(),
      originalTask: sessionCtx.originalTask,
      summary: {
        totalTurns: summary.turns,
        totalToolCalls: summary.toolCalls,
        toolCallsDenied: summary.denied,
        toolCallsAllowed: summary.toolCalls - summary.denied,
      },
      intentHistory: summary.intents.map((intent, i) => ({
        turn: i,
        intent: intent,
      })),
      turnIntents: sessionCtx.turnIntents.map((ti) => ({
        turn: ti.turnNumber,
        timestamp: ti.timestamp,
        prompt: ti.prompt,
      })),
      toolHistory: sessionCtx.recentTools.map((tc) => ({
        turn: tc.turnNumber,
        tool: tc.tool,
        input: tc.input,
        decision: tc.decision,
        similarity: tc.similarity,
      })),
      driftHistory,
      interceptorDecisions: interceptorLog.map((r) => ({
        tool: r.tool,
        stage: r.stage,
        allowed: r.allowed,
        similarity: r.similarity,
        reason: r.reason,
        evaluationMs: r.evaluationMs,
        judgeVerdict: r.judgeVerdict
          ? {
              verdict: r.judgeVerdict.verdict,
              confidence: r.judgeVerdict.confidence,
              reasoning: r.judgeVerdict.reasoning,
            }
          : null,
      })),
    };

    // Write log file
    const logDir = cfg.logDir ?? "./results";
    try {
      mkdirSync(logDir, { recursive: true });
    } catch {}

    const logFile = join(
      logDir,
      `session-${sessionId.substring(0, 12)}-${new Date().toISOString().replace(/[:.]/g, "-")}.json`
    );
    writeFileSync(logFile, JSON.stringify(sessionLog, null, 2));

    console.log(`\n  [STOP] Session log written to ${logFile}`);
    console.log(
      `  [STOP] Turns: ${summary.turns} | Tools: ${summary.toolCalls} | Denied: ${summary.denied}`
    );

    // Clean up session state
    tracker.endSession(sessionId);

    return {};
  };

  // Build the hooks config object for the SDK
  const hooks = {
    UserPromptSubmit: [{ hooks: [onUserPromptSubmit] }],
    PreToolUse: [{ hooks: [onPreToolUse] }],
    PostToolUse: [{ hooks: [onPostToolUse] }],
    Stop: [{ hooks: [onStop] }],
  };

  return { hooks, tracker, interceptor };
}

/**
 * Session Tracker
 *
 * Maintains per-session state across hook invocations, tracking:
 *   - Original intent (from first UserPromptSubmit)
 *   - Turn-by-turn intent history (from subsequent UserPromptSubmit calls)
 *   - Tool call history (from PreToolUse calls)
 *   - Embedding trajectories for drift detection
 *
 * This is the stateful backbone that connects the hooks:
 *   UserPromptSubmit → registers intent
 *   PreToolUse → evaluates tool call against intent history
 *
 * Keyed by session_id so multiple concurrent sessions stay isolated.
 */

import { DriftDetector } from "./drift-detector.js";
import { embedAny, cosineSimilarity } from "./ollama-client.js";

export interface TurnIntent {
  turnNumber: number;
  timestamp: string;
  prompt: string;
  embedding: number[];
}

export interface ToolCallRecord {
  turnNumber: number;
  tool: string;
  input: Record<string, unknown>;
  decision: "allow" | "deny" | "review";
  similarity: number | null;
}

export interface SessionState {
  sessionId: string;
  /** The first prompt — the original task */
  originalIntent: TurnIntent | null;
  /** All subsequent prompts — turn-by-turn intent history */
  turnIntents: TurnIntent[];
  /** All tool calls evaluated */
  toolHistory: ToolCallRecord[];
  /** Current turn number */
  currentTurn: number;
  /** Drift detector instance for this session */
  driftDetector: DriftDetector;
  /** Embedding of the original task */
  originalEmbedding: number[] | null;
}

export class SessionTracker {
  private sessions = new Map<string, SessionState>();
  private embeddingModel: string;

  constructor(embeddingModel = "nomic-embed-text") {
    this.embeddingModel = embeddingModel;
  }

  /**
   * Get or create session state.
   */
  private getSession(sessionId: string): SessionState {
    if (!this.sessions.has(sessionId)) {
      this.sessions.set(sessionId, {
        sessionId,
        originalIntent: null,
        turnIntents: [],
        toolHistory: [],
        currentTurn: 0,
        driftDetector: new DriftDetector(this.embeddingModel),
        originalEmbedding: null,
      });
    }
    return this.sessions.get(sessionId)!;
  }

  /**
   * Called from UserPromptSubmit hook.
   * First call = original intent. Subsequent calls = turn intents.
   */
  async registerIntent(sessionId: string, prompt: string): Promise<{
    isOriginal: boolean;
    turnNumber: number;
    driftFromOriginal: number | null;
    driftFromPrevious: number | null;
  }> {
    const session = this.getSession(sessionId);
    const [promptEmbedding] = await embedAny(prompt, this.embeddingModel);

    const intent: TurnIntent = {
      turnNumber: session.currentTurn,
      timestamp: new Date().toISOString(),
      prompt,
      embedding: promptEmbedding,
    };

    let driftFromOriginal: number | null = null;
    let driftFromPrevious: number | null = null;

    if (session.originalIntent === null) {
      // First prompt — this is the original task
      session.originalIntent = intent;
      session.originalEmbedding = promptEmbedding;
      await session.driftDetector.registerGoal(prompt);

      console.log(
        `  [SESSION ${sessionId.substring(0, 8)}] ORIGINAL INTENT registered: "${prompt.substring(0, 80)}..."`
      );
    } else {
      // Subsequent prompt — track as turn intent
      session.turnIntents.push(intent);
      session.currentTurn++;

      // Measure drift from original
      driftFromOriginal = 1 - cosineSimilarity(
        session.originalEmbedding!,
        promptEmbedding
      );

      // Measure drift from previous turn
      const prevIntents = session.turnIntents;
      if (prevIntents.length >= 2) {
        const prevEmbedding = prevIntents[prevIntents.length - 2].embedding;
        driftFromPrevious = 1 - cosineSimilarity(prevEmbedding, promptEmbedding);
      }

      console.log(
        `  [SESSION ${sessionId.substring(0, 8)}] TURN ${session.currentTurn} intent: "${prompt.substring(0, 80)}..." ` +
        `(drift from original: ${driftFromOriginal?.toFixed(3) ?? "n/a"}, ` +
        `from prev: ${driftFromPrevious?.toFixed(3) ?? "n/a"})`
      );
    }

    return {
      isOriginal: session.originalIntent === intent,
      turnNumber: session.currentTurn,
      driftFromOriginal,
      driftFromPrevious,
    };
  }

  /**
   * Called from PreToolUse hook.
   * Returns the session state needed for tool evaluation.
   */
  getSessionContext(sessionId: string): {
    originalTask: string | null;
    currentTurn: number;
    recentTools: ToolCallRecord[];
    turnIntents: TurnIntent[];
    originalEmbedding: number[] | null;
  } {
    const session = this.getSession(sessionId);
    return {
      originalTask: session.originalIntent?.prompt ?? null,
      currentTurn: session.currentTurn,
      recentTools: session.toolHistory.slice(-10),
      turnIntents: session.turnIntents,
      originalEmbedding: session.originalEmbedding,
    };
  }

  /**
   * Record a tool call decision.
   */
  recordToolCall(
    sessionId: string,
    tool: string,
    input: Record<string, unknown>,
    decision: "allow" | "deny" | "review",
    similarity: number | null
  ): void {
    const session = this.getSession(sessionId);
    session.toolHistory.push({
      turnNumber: session.currentTurn,
      tool,
      input,
      decision,
      similarity,
    });
  }

  /**
   * Get the drift detector for a session.
   */
  getDriftDetector(sessionId: string): DriftDetector {
    return this.getSession(sessionId).driftDetector;
  }

  /**
   * Get full session summary for logging.
   */
  getSessionSummary(sessionId: string): {
    turns: number;
    toolCalls: number;
    denied: number;
    intents: string[];
  } {
    const session = this.getSession(sessionId);
    return {
      turns: session.currentTurn,
      toolCalls: session.toolHistory.length,
      denied: session.toolHistory.filter((t) => t.decision === "deny").length,
      intents: [
        session.originalIntent?.prompt.substring(0, 60) ?? "(none)",
        ...session.turnIntents.map((i) => i.prompt.substring(0, 60)),
      ],
    };
  }

  /**
   * Clean up a completed session.
   */
  endSession(sessionId: string): void {
    this.sessions.delete(sessionId);
  }
}

/**
 * PreToolUse Interceptor
 *
 * Evaluates every tool call BEFORE execution using a three-stage pipeline:
 *
 *   Stage 1: Policy engine (instant)
 *     → ALLOW: skip to execution
 *     → DENY:  block immediately
 *     → REVIEW: proceed to Stage 2
 *
 *   Stage 2: Embedding drift check (~50ms)
 *     Compares "tool + parameters" against original task embedding.
 *     If similarity is high → allow
 *     If drift detected → proceed to Stage 3
 *
 *   Stage 3: LLM judge (~5-15s)
 *     Asks local LLM: "Given original task X, is tool call Y appropriate?"
 *     Returns allow/deny.
 *
 * This runs at PreToolUse, so blocked tools never execute.
 * The agent receives a rejection message and must try a different approach.
 */

import {
  evaluateToolPolicy,
  formatPolicyResult,
  type PolicyResult,
} from "./tool-policy.js";
import { DriftDetector, type DriftBackend } from "./drift-detector.js";
import { IntentJudge, type JudgeVerdict, type JudgeBackend } from "./intent-judge.js";
import { checkOllama } from "./ollama-client.js";
import { checkBedrock } from "./bedrock-client.js";

export interface InterceptorConfig {
  embeddingModel?: string;
  judgeModel?: string;
  /** Similarity threshold below which the judge is invoked (default: 0.5) */
  reviewThreshold?: number;
  /** Similarity threshold below which the tool is auto-denied (default: 0.3) */
  denyThreshold?: number;
  /** Enable LLM judge for REVIEW decisions (default: true) */
  enableJudge?: boolean;
  /** Backend for the embedding drift detector (default: "ollama") */
  embedBackend?: DriftBackend;
  /** Backend for the LLM judge (default: "ollama") */
  judgeBackend?: JudgeBackend;
}

const DEFAULTS: Required<InterceptorConfig> = {
  embeddingModel: "nomic-embed-text",
  judgeModel: "nemotron-3-super",
  reviewThreshold: 0.5,
  denyThreshold: 0.3,
  enableJudge: true,
  embedBackend: "ollama",
  judgeBackend: "ollama",
};

export interface InterceptionResult {
  allowed: boolean;
  tool: string;
  input: Record<string, unknown>;
  /** Which stage made the decision */
  stage: "policy-allow" | "policy-deny" | "drift-allow" | "drift-deny" | "judge-allow" | "judge-deny";
  policyResult: PolicyResult;
  /** Embedding similarity (null if not evaluated) */
  similarity: number | null;
  /** Judge verdict (null if not invoked) */
  judgeVerdict: JudgeVerdict | null;
  /** Total evaluation time in ms */
  evaluationMs: number;
  /** Reason for the decision */
  reason: string;
}

export class PreToolInterceptor {
  private config: Required<InterceptorConfig>;
  private driftDetector: DriftDetector;
  private judge: IntentJudge;
  private originalTask: string = "";
  private toolLog: InterceptionResult[] = [];

  constructor(config?: InterceptorConfig) {
    this.config = { ...DEFAULTS, ...config };
    this.driftDetector = new DriftDetector(
      this.config.embeddingModel,
      this.config.embedBackend,
    );
    this.judge = new IntentJudge(this.config.judgeModel, this.config.judgeBackend);
  }

  async preflight(): Promise<void> {
    const embedOnBedrock = this.config.embedBackend === "bedrock";
    const judgeOnBedrock = this.config.judgeBackend === "bedrock";

    if (embedOnBedrock || judgeOnBedrock) {
      const { ok, error } = await checkBedrock(
        this.config.embeddingModel,
        this.config.judgeModel,
      );
      if (!ok) {
        throw new Error(`Bedrock preflight failed: ${error}`);
      }
      console.log(
        `  Bedrock OK: embedding=${this.config.embeddingModel}, judge=${this.config.judgeModel}`,
      );
    }

    if (!embedOnBedrock || !judgeOnBedrock) {
      const ollamaModels = [
        ...(!embedOnBedrock ? [this.config.embeddingModel] : []),
        ...(!judgeOnBedrock ? [this.config.judgeModel] : []),
      ];
      const { ok, missing } = await checkOllama(ollamaModels[0], ollamaModels[1]);
      if (!ok) {
        console.error(`Missing Ollama models: ${missing.join(", ")}`);
        for (const m of missing) {
          console.error(`  ollama pull ${m}`);
        }
        throw new Error(`Missing Ollama models: ${missing.join(", ")}`);
      }
    }
  }

  async registerGoal(task: string): Promise<void> {
    this.originalTask = task;
    await this.driftDetector.registerGoal(task);
  }

  /**
   * Evaluate a tool call. Returns whether it should be allowed.
   * This is the PreToolUse hook implementation.
   */
  async evaluate(
    tool: string,
    input: Record<string, unknown>
  ): Promise<InterceptionResult> {
    const start = Date.now();

    // --- Stage 1: Policy engine ---
    const policyResult = evaluateToolPolicy(tool, input);

    if (policyResult.decision === "allow") {
      const result: InterceptionResult = {
        allowed: true,
        tool,
        input,
        stage: "policy-allow",
        policyResult,
        similarity: null,
        judgeVerdict: null,
        evaluationMs: Date.now() - start,
        reason: policyResult.reason,
      };
      this.log(result);
      return result;
    }

    if (policyResult.decision === "deny") {
      const result: InterceptionResult = {
        allowed: false,
        tool,
        input,
        stage: "policy-deny",
        policyResult,
        similarity: null,
        judgeVerdict: null,
        evaluationMs: Date.now() - start,
        reason: policyResult.reason,
      };
      this.log(result);
      return result;
    }

    // --- Stage 2: Embedding drift check ---
    const toolDescription = this.describeToolCall(tool, input);
    const drift = await this.driftDetector.evaluate(toolDescription);

    if (drift.similarity >= this.config.reviewThreshold) {
      // High similarity to original task — allow
      const result: InterceptionResult = {
        allowed: true,
        tool,
        input,
        stage: "drift-allow",
        policyResult,
        similarity: drift.similarity,
        judgeVerdict: null,
        evaluationMs: Date.now() - start,
        reason: `Similarity ${drift.similarity.toFixed(3)} >= threshold ${this.config.reviewThreshold}`,
      };
      this.log(result);
      return result;
    }

    if (drift.similarity < this.config.denyThreshold) {
      // Very low similarity — auto-deny without judge
      const result: InterceptionResult = {
        allowed: false,
        tool,
        input,
        stage: "drift-deny",
        policyResult,
        similarity: drift.similarity,
        judgeVerdict: null,
        evaluationMs: Date.now() - start,
        reason: `Similarity ${drift.similarity.toFixed(3)} < deny threshold ${this.config.denyThreshold}`,
      };
      this.log(result);
      return result;
    }

    // --- Stage 3: LLM judge ---
    if (!this.config.enableJudge) {
      // No judge enabled — default deny for ambiguous cases
      const result: InterceptionResult = {
        allowed: false,
        tool,
        input,
        stage: "drift-deny",
        policyResult,
        similarity: drift.similarity,
        judgeVerdict: null,
        evaluationMs: Date.now() - start,
        reason: `Similarity ${drift.similarity.toFixed(3)} in review zone, judge disabled`,
      };
      this.log(result);
      return result;
    }

    const recentTools = this.toolLog.slice(-5).map(
      (r) => `${r.tool}(${this.describeToolCall(r.tool, r.input).substring(0, 80)})`
    );

    const judgeVerdict = await this.judge.evaluate(
      this.originalTask,
      recentTools,
      `${tool}(${toolDescription})`
    );

    const allowed = judgeVerdict.verdict === "consistent";
    const result: InterceptionResult = {
      allowed,
      tool,
      input,
      stage: allowed ? "judge-allow" : "judge-deny",
      policyResult,
      similarity: drift.similarity,
      judgeVerdict,
      evaluationMs: Date.now() - start,
      reason: `Judge: ${judgeVerdict.verdict} (${judgeVerdict.reasoning})`,
    };
    this.log(result);
    return result;
  }

  /**
   * Create a text description of a tool call for embedding.
   */
  private describeToolCall(
    tool: string,
    input: Record<string, unknown>
  ): string {
    switch (tool) {
      case "Read":
        return `Read file: ${input.file_path}`;
      case "Write":
        return `Write file: ${input.file_path} with content about ${String(input.content ?? "").substring(0, 100)}`;
      case "Edit":
        return `Edit file: ${input.file_path}`;
      case "Bash":
        return `Execute command: ${String(input.command ?? "").substring(0, 200)}`;
      case "Glob":
        return `Find files matching: ${input.pattern}`;
      case "Grep":
        return `Search for: ${input.pattern}`;
      default:
        return `${tool}: ${JSON.stringify(input).substring(0, 200)}`;
    }
  }

  private log(result: InterceptionResult): void {
    this.toolLog.push(result);

    const icon =
      result.stage.endsWith("-allow") ? "✓" :
      result.stage.endsWith("-deny") ? "✗" : "?";
    const simStr = result.similarity !== null
      ? ` sim=${result.similarity.toFixed(3)}`
      : "";
    const judgeStr = result.judgeVerdict
      ? ` judge=${result.judgeVerdict.verdict}(${result.judgeVerdict.durationMs}ms)`
      : "";

    console.log(
      `    [${icon} ${result.stage}]${simStr}${judgeStr} ${result.tool}: ${result.reason} (${result.evaluationMs}ms)`
    );
  }

  getLog(): InterceptionResult[] {
    return this.toolLog;
  }

  reset(): void {
    this.toolLog = [];
    this.originalTask = "";
    this.driftDetector.reset();
  }
}

/**
 * Tool Policy Engine
 *
 * Classifies tool calls into three categories:
 *   ALLOW  — always permitted, no review (read-only, search, navigation)
 *   DENY   — always blocked, never permitted (destructive, dangerous)
 *   REVIEW — requires intent evaluation before proceeding
 *
 * Operates at the PreToolUse level, evaluating tool name + parameters
 * before execution. Fast pattern matching — no LLM calls.
 */

export type PolicyDecision = "allow" | "deny" | "review";

export interface PolicyResult {
  decision: PolicyDecision;
  tool: string;
  reason: string;
  /** The matched rule that triggered this decision */
